style.css:
@-moz-document domain("github.com") {
:root {
    --ctp-base: #1e1e2e;
    --ctp-mantle: #181825;
    --ctp-crust: #11111b;
    --ctp-surface0: #313244;
    --ctp-surface1: #45475a;
    --ctp-overlay: #6c7086;
    --ctp-text: #cdd6f4;
    --ctp-subtext: #a6adc8;
    --ctp-blue: #89b4fa;
    --ctp-blue-muted: #5278a8;
    --ctp-sky: #74c7ec;
    --ctp-mauve: #cba6f7;
    --ctp-green: #a6e3a1;
    --ctp-yellow: #f9e2af;
    --ctp-red: #f38ba8;
  }

  /* Fondos generales */
  html,
  body,
  .logged-in.env-production.page-responsive {
    background: var(--ctp-base) !important;
    color: var(--ctp-text) !important;
  }

  .Header,
  .AppHeader,
  .AppHeader-globalBar,
  .AppHeader-context {
    background: var(--ctp-crust) !important;
    border-color: var(--ctp-surface0) !important;
  }

  .color-bg-default,
  .color-bg-subtle,
  .Box,
  .blankslate,
  .markdown-body,
  .discussion-timeline-actions,
  .repository-content {
    background-color: var(--ctp-base) !important;
  }

  .color-bg-inset,
  .color-bg-tertiary,
  .Box-header,
  .js-notification-shelf,
  .file-header,
  .react-directory-row {
    background-color: var(--ctp-mantle) !important;
  }

  /* Texto */
  .color-fg-default,
  .color-fg-muted,
  .markdown-body,
  .markdown-body p,
  .markdown-body li,
  .markdown-body td {
    color: var(--ctp-text) !important;
  }

  .color-fg-subtle,
  .text-small,
  .text-gray,
  .fgColor-muted {
    color: var(--ctp-subtext) !important;
  }

  /* Bordes discretos */
  .border,
  .border-top,
  .border-bottom,
  .border-left,
  .border-right,
  .Box,
  .Box-row,
  .UnderlineNav,
  .js-details-container,
  .TimelineItem::before {
    border-color: var(--ctp-surface0) !important;
  }

  /* Enlaces y botones azules suaves */
  a,
  .Link--primary {
    color: var(--ctp-blue) !important;
  }

  a:hover {
    color: var(--ctp-sky) !important;
  }

  .btn-primary {
    background: #456a96 !important;
    border-color: #5278a8 !important;
    color: #eff5ff !important;
  }

  .btn-primary:hover {
    background: #5278a8 !important;
  }

  .btn {
    background: var(--ctp-surface0) !important;
    border-color: var(--ctp-surface1) !important;
    color: var(--ctp-text) !important;
  }

  .btn:hover {
    background: #3c4962 !important;
  }

  /* Campos de búsqueda y texto */
  input,
  textarea,
  .form-control,
  .FormControl-input,
  .form-select {
    background: var(--ctp-mantle) !important;
    color: var(--ctp-text) !important;
    border-color: var(--ctp-surface1) !important;
  }

  input:focus,
  textarea:focus,
  .form-control:focus {
    border-color: var(--ctp-blue-muted) !important;
    box-shadow: 0 0 0 3px rgba(82, 120, 168, 0.22) !important;
  }

  /* Código */
  pre,
  .highlight,
  .highlight pre,
  .blob-code-inner,
  .react-code-text,
  .commit-tease-sha {
    background: #171a29 !important;
    color: #d6e1ff !important;
  }

  .markdown-body code,
  code {
    background: #292b3d !important;
    color: #b8d4ff !important;
  }

  /* Archivos, issues y PR */
  .js-navigation-item:hover,
  .react-directory-row:hover,
  .Box-row:hover {
    background: #252b40 !important;
  }

  .selected,
  .UnderlineNav-item.selected,
  .UnderlineNav-item[aria-current="page"] {
    color: var(--ctp-blue) !important;
    border-bottom-color: var(--ctp-blue-muted) !important;
  }

  /* Estados */
  .State--open,
  .IssueLabel {
    background-color: #294a42 !important;
    color: var(--ctp-green) !important;
  }

  .State--closed,
  .State--merged {
    background-color: #51354d !important;
    color: var(--ctp-mauve) !important;
  }

  .Label--danger {
    background-color: #563440 !important;
    color: var(--ctp-red) !important;
  }

  /* Scrollbar */
  * {
    scrollbar-color: #52647e var(--ctp-mantle);
  }
}
